mapper.select:
select
  PATIENT_ID, VISIT_ID, DIAGNOSIS_TYPE, DIAGNOSIS_NO, DIAGNOSIS_DESC, DIAGNOSIS_DATE, TREAT_DAYS, TREAT_RESULT, OPER_TREAT_INDICATOR, DIAGNOSIS_CODE, ADMISSION_CONDITION, DIAGNOSIS_POSITION, PATHOLOGY_NO, DIAGNOSIS_CODE_LOCAL, DIAGNOSIS_MEMO
from diagnosis


        and PATIENT_ID = #{patientId}


        and VISIT_ID = #{visitId}


        and DIAGNOSIS_TYPE = #{diagnosisType}


        and DIAGNOSIS_NO = #{diagnosisNo}


        and DIAGNOSIS_DESC = #{diagnosisDesc}


        and DIAGNOSIS_DATE = #{diagnosisDate}


        and TREAT_DAYS = #{treatDays}


        and TREAT_RESULT = #{treatResult}


        and OPER_TREAT_INDICATOR = #{operTreatIndicator}


        and DIAGNOSIS_CODE = #{diagnosisCode}


        and ADMISSION_CONDITION = #{admissionCondition}


        and DIAGNOSIS_POSITION = #{diagnosisPosition}


        and PATHOLOGY_NO = #{pathologyNo}


        and DIAGNOSIS_CODE_LOCAL = #{diagnosisCodeLocal}


        and DIAGNOSIS_MEMO = #{diagnosisMemo}


limit #{pageable.offset}, #{pageable.pageSize}

